/* ===== 用語辞典 ===== */
var G={
"service-account":{en:"Shared service account",ja:"共有サービスアカウント",d:"プログラム用の共通ID。便利だが全員が同じ強い権限になるため、①本来見えないデータに届く ②誰の操作か分からない、の2つを同時に生む。試験では<b>ほぼ常に「悪い現状」</b>として登場する。"},
"identity-propagation":{en:"Identity propagation / on-behalf-of",ja:"認可の伝播",d:"エージェントが外部APIを叩くとき、<b>エージェント自身ではなく「依頼した人間ユーザー」の権限で</b>実行させること。代理で窓口に行くとき、本人の身分証を持っていくイメージ。"},
"scoped-credential":{en:"Scoped credential / short-lived token",ja:"スコープ限定の資格情報",d:"「この人の・この操作だけ」に絞った短命の鍵。マスターキーではなく特定の部屋だけ開く鍵。漏れても被害範囲が小さい。"},
"privilege-escalation":{en:"Privilege escalation",ja:"権限昇格",d:"本来持っていないはずの権限を手に入れてしまうこと。共有アカウント運用で最も起きやすい。"},
"attack-surface":{en:"Attack surface",ja:"攻撃面",d:"攻撃されうる入口の総量。<b>ログや確認ダイアログを足しても攻撃面は減らない</b>（能力が残っているから）。"},
"least-privilege":{en:"Least privilege",ja:"最小権限",d:"必要な権限だけを与える原則。CCAR-Pでは<b>「監視する」ではなく「能力そのものを消す」</b>ことを指す。"},
"deterministic":{en:"Deterministic enforcement",ja:"決定論的強制",d:"「絶対に」を満たせるのはコード・スキーマ・権限だけ。<b>promptはお願いであって保証ではない。</b>この原則だけで解ける問題が毎回複数出る。"},
"acl":{en:"ACL (Access Control List)",ja:"アクセス制御リスト",d:"「この文書は誰が見てよいか」の一覧。RAGでは<b>検索する前に</b>これで絞る(pre-filter)のが正解。"},
"pre-filter":{en:"Pre-filter / metadata filtering",ja:"事前フィルタ",d:"検索段階で権限外の文書を候補から外すこと。生成後に隠すのでは、ログ・キャッシュ・traceに残って漏洩経路になる。"},
"fail-closed":{en:"Fail closed",ja:"安全側に倒す",d:"判断がつかないときは「許可しない」側で止める設計。逆はfail open（危険）。"},
"prompt-injection":{en:"Prompt injection",ja:"プロンプトインジェクション",d:"外部データ（PDF・Web・メール）に「全部消せ」等の指示文を仕込みAIを乗っ取る攻撃。<b>最終防衛線は危険なtoolを最初から与えないこと。</b>"},
"audit-trail":{en:"Audit trail / provenance",ja:"監査証跡",d:"「誰が・いつ・どの版で・何を承認して・何が起きたか」を後から再構成できる記録。<b>量ではなく再構成可能性</b>が本質。"},
"tool-use-loop":{en:"Tool use loop",ja:"ツール実行ループ",d:"①tool定義を渡す→②モデルがtool_useを返す→③<b>アプリが実際に実行</b>→④tool_resultを返す→⑤最終応答。<b>モデルはtoolを実行しない</b>ので権限チェックはアプリ側の責任。"},
"capability-bloat":{en:"Capability bloat",ja:"能力の肥大化",d:"toolを付けすぎた状態。①選択ミスが増える ②contextを食う ③攻撃面が広がる、の三重苦。"},
"trace":{en:"Trace / span",ja:"トレース・スパン",d:"<b>1タスク＝1本の記録(trace)</b>。その中の1工程（LLM呼出1回、tool実行1回）がspan。これが無いと「どのステップで壊れたか」が言えない。"},
"observability":{en:"Observability",ja:"可観測性",d:"外から内部状態が分かること。<b>再現できない不具合は直せない</b>ので、観測設計＝デバッグ能力。"},
"p95":{en:"p95 / tail latency",ja:"95パーセンタイル遅延",d:"<b>平均は遅さを隠す。</b>平均1.1秒でもp95が4秒なら20回に1回は遅い。SLAは通常p95で定義するので、監視もp95で行う。"},
"sampling":{en:"Sampling / tiered logging",ja:"サンプリング・階層化ログ",d:"大規模では<b>メトリクスは全件・詳細payloadはサンプリング＋エラー時のみ・PIIはマスキング＋保持期間</b>の3階層が定石。"},
"pii":{en:"PII",ja:"個人情報",d:"氏名・住所・カルテなど個人を特定できる情報。ログに生で残すのは規制違反になりうる。"},
"stop-reason":{en:"stop_reason",ja:"停止理由",d:"応答が終わった理由。end_turn=自然終了 / max_tokens=上限で切れた / tool_use=ツールを呼びたい。<b>max_tokens打ち切りは品質障害の重要シグナル。</b>"},
"aggregate-mask":{en:"Aggregate masks segments",ja:"集約値はセグメントを隠す",d:"全体95%でも特定業種だけ60%という構造は頻出。必ず言語別・文書種別・顧客別に割って見る。公平性検証も同じ論法。"},
"prompt-caching":{en:"Prompt caching",ja:"プロンプトキャッシュ",d:"同じ前置きの<b>計算結果</b>を再利用し、コスト減＋初回応答(TTFT)短縮。<b>送信を省略するのではない</b>——毎回全部送る。"},
"stable-prefix":{en:"Stable prefix",ja:"安定した接頭部",d:"キャッシュは<b>先頭からの完全一致</b>にしか効かない。配置は【固定:system→policy→tools→few-shot】→【可変:履歴・入力】。<b>タイムスタンプ混入で即死。</b>"},
"modular-prompt":{en:"Modular prompt",ja:"モジュラープロンプト",d:"共通ブロックを1箇所に定義して参照する方式。目的は<b>内容の再利用（更新の一元化）</b>。cachingとは目的が違う。"},
"agent-skills":{en:"Agent Skills",ja:"エージェントスキル",d:"手順・資料・スクリプトをまとめた再利用単位。<b>必要な時だけ読み込む</b>ので常時のcontext消費を抑えられる。"},
"single-source":{en:"Single source of truth",ja:"単一の正本",d:"「コピーして配る」は再利用ではない（更新が追随しない）。<b>一元定義＋参照</b>が正解。"},
"progressive-discovery":{en:"Progressive discovery",ja:"段階的発見（必要時取得）",d:"必要になった時に取りに行く方式。<b>量が多く可変性が高い</b>情報に適する。"},
"monolithic-context":{en:"Monolithic context",ja:"一括投入",d:"最初から全部contextに積む方式。<b>小さく安定した</b>情報にのみ適する。「入ること」と「有効であること」は別。"},
"context-window":{en:"Context window",ja:"コンテキストウィンドウ",d:"1リクエストに入る上限。<b>容量であり予算でもある</b>——無関係な文脈は精度を下げ、コストとlatencyを増やす。"},
"router":{en:"Router",ja:"ルーター",d:"入力の難易度で「定型は小型モデル／複雑は上位モデル」に振り分ける仕組み。<b>単一モデル統一は必ずコストか精度を犠牲にする。</b>"},
"extended-thinking":{en:"Extended thinking",ja:"拡張思考",d:"推論量を増やす設定。コストとlatencyを押し上げるので<b>常時ONにしない</b>。思考トークン量は品質指標ではない。"},
"message-batches":{en:"Message Batches",ja:"メッセージバッチ",d:"大量リクエストをまとめて非同期処理する仕組み。<b>判断は「人が待っているか」の一点</b>——待っている=同期、待っていない=batch。"},
"streaming":{en:"Streaming",ja:"ストリーミング",d:"生成され次第トークンを送る方式。<b>体感待ち時間は改善するが、総処理時間もコストも変わらない。</b>"},
"non-inferiority":{en:"Non-inferiority margin",ja:"非劣性マージン",d:"「ここまでの精度低下なら許容する」と<b>事前に</b>決める数値。モデル変更の判断に必須。"},
"representative-eval":{en:"Representative eval set",ja:"代表評価セット",d:"本番の入力分布を反映したテストデータ。<b>公開ベンチマークは自タスクを代表しない。</b>過去の障害事例を必ず入れる。"},
"llm-as-judge":{en:"LLM-as-judge",ja:"LLMによる採点",d:"AIに採点させる方式。<b>判定者も検証対象</b>——人手ラベルとの一致率を確認してから信用する。"},
"regression-test":{en:"Regression test",ja:"回帰テスト",d:"変更で既存機能が壊れていないか確認するテスト。<b>prompt変更もコード変更と同じ</b>——eval setをCIで回してから出す。"},
"canary":{en:"Canary / shadow",ja:"カナリア・シャドー",d:"本番の数%だけ新版に流す(canary)、裏で並走させ結果は返さず比較(shadow)。<b>比較対象を残す</b>のが要点。"},
"mcp":{en:"MCP (Model Context Protocol)",ja:"MCP",d:"モデルと外部データ・機能をつなぐ標準規格。<b>resources=読む(副作用なし)／tools=実行する(副作用あり)</b>。接続方式であって<b>認可の仕組みではない</b>。"},
"a2a":{en:"Agent-to-agent",ja:"エージェント間通信",d:"自律的な相手に作業を委譲する方式。最も自由度が高く、<b>最も観測とデバッグが難しい</b>。"},
"rag":{en:"RAG",ja:"検索拡張生成",d:"関連文書を検索してからモデルに渡す方式。<b>自信満々の誤答はまずretrievalを疑う。</b>診断順: recall→precision/rerank→chunk→引用強制→最後にモデル。"},
"stale-chunk":{en:"Stale chunks",ja:"古い断片",d:"再インデックス失敗で残った旧版の文書断片。<b>文書更新直後</b>の品質劣化の典型原因。"},
"hybrid-search":{en:"Hybrid search",ja:"ハイブリッド検索",d:"キーワード検索＋ベクトル検索の併用。<b>型番・エラーコードのような完全一致はベクトルが最も苦手。</b>"},
"discovery":{en:"Structured discovery",ja:"構造化ディスカバリー",d:"解ではなく<b>問題</b>を特定する工程。必ず聞く5点＝①現状フロー②件数③失敗時の影響④既存の判断基準⑤成功の測り方。"},
"sla":{en:"SLA / expectation alignment",ja:"SLA・期待値調整",d:"「誰が・いつまでに・どの数値を」守るかの約束。<b>期待値は言葉ではなく数値と手順で揃える。</b>"},
"adr":{en:"ADR / Decision record",ja:"アーキテクチャ決定記録",d:"「なぜこの案を採り、どの案を捨てたか」の記録。<b>これが無いと後任は安全に変更できない</b>（禁じ手を踏む・再発明する）。"},
"runbook":{en:"Runbook",ja:"運用手順書",d:"障害時に誰が何をするかの手順書。handoffの必須要素。"},
"named-owner":{en:"Named owner",ja:"明示的な責任者",d:"<b>監視は仕組みだけでは動かない。</b>ownerとSLAが紐づいて初めて運用になる。"},
"production-readiness":{en:"Production readiness",ja:"本番適合性",d:"規模・SLA・権限・監査・障害対応・rollback・owner・runbookまで揃った状態。<b>PoC成功 ≠ 本番可。</b>"},
"hitl":{en:"Human-in-the-loop",ja:"人間の介在",d:"置き場所は<b>「不可逆 × 高影響 × 低信頼」の交点</b>だけ。全件レビューは形骸化して統制を失う。"},
"guardrail":{en:"Guardrail / defense in depth",ja:"ガードレール・多層防御",d:"入力側(injection・PII)／実行側(権限・上限・allowlist)／出力側(スキーマ・根拠有無)の<b>多層</b>で持つ。"},
"hook":{en:"Hook",ja:"フック",d:"特定タイミングで必ずコマンドを実行する仕組み。<b>必ず起きてほしいことを、モデルや人の記憶に任せない。</b>"},
"claude-md":{en:"CLAUDE.md / shared settings",ja:"メモリファイル・共有設定",d:"毎回伝えたい前提・規約を常設するファイル。チーム標準は<b>リポジトリにコミット</b>して共有、個人の好みはローカル。"},
"structured-outputs":{en:"Structured outputs / JSON Schema",ja:"構造化出力",d:"スキーマで出力形式を強制する機能。<b>形は保証するが、正しさは保証しない。</b>値の妥当性は別途コードで検証。"},
"few-shot":{en:"Few-shot / chain-of-thought",ja:"few-shot・CoT",d:"few-shotは<b>判断基準の提示</b>に効く（知識供給はretrievalの仕事）。CoTは多段推論が要る時だけ——定型抽出に常用するとコストが増えるだけ。"},
"tco":{en:"TCO",ja:"総保有コスト",d:"token単価だけでなく再試行・人手レビュー・保守・障害対応まで含めた総額。<b>安いモデルにして人手レビューが増えれば逆に高くつく。</b>"},
"feedback-loop":{en:"Feedback loop / drift",ja:"フィードバックループ",d:"人の修正・却下を収集しeval setと監視に還流する経路。<b>end-to-end設計にはこれが含まれる。</b>無いと静かに劣化する。"},
"sysprompt":{en:"System prompt",ja:"システムプロンプト",d:"役割・制約・出力方針を与える土台。<b>ベースラインは作れるが保証は作れない。</b>硬い要件はコード側で強制する。"},
"evalset":{en:"Eval set",ja:"評価セット",d:"品質を数値で測るためのテストデータ集合。<b>代表性・境界条件・過去障害</b>の3点が揃って初めて測定器になる。"},
"e2e":{en:"End-to-end architecture",ja:"エンドツーエンド設計",d:"入力〜処理〜検証〜人間の介在〜フィードバックまでを一続きで設計すること。<b>モデル選定は一部分にすぎない。</b>"},
"lifecycle":{en:"Lifecycle / handoff",ja:"ライフサイクル・引き継ぎ",d:"構築後の運用・劣化対応・引き継ぎまで含めた全期間。<b>ADR・runbook・named ownerが3点セット。</b>"}};

